#!/usr/bin/env bash
# Bootstrap Gitea admin + converge mirror repos
# Source: build.json .gitea.mirrors + .gitea.mirror_policy.exclude + secrets.yaml
# Run: automatically, as the ship engine's compose post-hook — declared in
#      build.json .compose.post_hook = "configs/init-mirrors.sh". The engine
#      wipes <DEPLOY_PATH>/.posthook-receipt, runs this script, and writes a
#      revision-scoped token there only if it exits 0, so a hook that did not
#      run cannot report green. The header used to claim "container-init calls
#      this"; nothing did. No systemd unit, cron entry, compose hook or ship
#      step referenced it, the deploy only COPIED it, and the mirror set only
#      ever moved when somebody ran it by hand.
# Idempotent: safe to run multiple times
#
# PRIVATE mirrors need auth_token in the migrate payload (anonymous clone of
# a private repo yields an empty mirror). Read at runtime from the
# GITHUB_MIRROR_TOKEN key of infra-dat_gitea/src/secrets.yaml (sops), whose
# _credentials.github_mirror record names its vault source. A private mirror
# that is, or would be, empty without it fails this script (see Verdict).
# The token is offered ONLY to converge_mirror calls for names NOT in
# mirror_policy.exclude, and excluded repos are DELETED by step 3.5 before any
# migrate is attempted — so it cannot sweep an excluded repo in.
set -uo pipefail
API="http://localhost:3002/api/v1"
CONTAINER="gitea"

# ── Secrets ───────────────────────────────────────────────────────────
# Sourced, not inherited. The post-hook is invoked as
#   cd <DEPLOY_PATH> && ./configs/init-mirrors.sh
# with no environment of its own, so GITEA_ADMIN_* (and the optional
# GITHUB_MIRROR_TOKEN) have to be read from the dotenv the same deploy just
# wrote one directory up. Missing values are fatal here rather than three
# steps later as an opaque 401 from the token endpoint.
SECRETS_ENV="$(cd "$(dirname "$0")/.." && pwd)/.secrets"
if [ -f "$SECRETS_ENV" ]; then
  set -a; . "$SECRETS_ENV"; set +a
fi
for _required in GITEA_ADMIN_USER GITEA_ADMIN_PASSWORD GITEA_ADMIN_EMAIL; do
  eval "_required_value=\${$_required:-}"
  if [ -z "$_required_value" ]; then
    echo "[init-mirrors] FAILED: $_required is unset (looked in $SECRETS_ENV)" >&2
    exit 1
  fi
done

# ── Per-repo outcome accounting ───────────────────────────────────────
# Every mirror used to be provisioned as
#   api -X POST ... && echo "  OK <repo>" || echo "  FAIL <repo>"
# which prints FAIL and exits 0. Twenty-nine repos could fail to migrate and
# this script still reported success — the same silent-skip class that left
# four declared mail accounts non-existent for a day while the MX accepted
# their mail. Counts live in FILES rather than shell variables because a
# variable incremented inside a pipeline or command-substitution subshell is
# discarded on subshell exit, which is exactly how a loop counts failures and
# then reports none.
TALLY_DIR=$(mktemp -d /tmp/.gitea-init-mirrors-tally.XXXXXX)
trap 'rm -rf "$TALLY_DIR"' EXIT
tally()       { echo "$2" >> "$TALLY_DIR/$1"; }
tally_count() { _c=$(cat "$TALLY_DIR/$1" 2>/dev/null | wc -l | tr -d ' '); echo "${_c:-0}"; }

# Admin credentials go to curl as a config on stdin (-K -), never as -u in
# argv, where every process on the VM can read them.
admin_curl() {
  printf 'user = "%s:%s"\n' \
    "$(printf '%s' "$GITEA_ADMIN_USER" | sed 's/[\\"]/\\&/g')" \
    "$(printf '%s' "$GITEA_ADMIN_PASSWORD" | sed 's/[\\"]/\\&/g')" | curl -K - "$@"
}
admin_auth_code() { admin_curl -s -o /dev/null -w '%{http_code}' "$API/user"; }
# gitea refuses to run its CLI as root (mustNotRunAsRoot), which is what a bare
# `docker exec` is, so every CLI call runs as the image's `git` user.
gitea_user() { docker exec -u git "$CONTAINER" gitea admin user "$@"; }

# Step 1: Converge the admin user to the declared credential (idempotent)
# The create used to run as root and pipe through `grep -v "already exists" ||
# true`, so gitea's root refusal was swallowed and nothing ever applied
# GITEA_ADMIN_PASSWORD: the live password had drifted from the declared one and
# no ship noticed. Now the declared password is checked against the live API
# and, if it is rejected, applied with change-password and checked again. A
# rotation is a sops edit plus a ship, and a ship cannot go green while
# declared != live.
echo "-- Converging admin user --"
if ! out=$(gitea_user create \
    --username "${GITEA_ADMIN_USER}" \
    --password "${GITEA_ADMIN_PASSWORD}" \
    --email "${GITEA_ADMIN_EMAIL}" \
    --admin \
    --must-change-password=false 2>&1); then
  case "$out" in
    *"already exists"*) ;;
    *) echo "[init-mirrors] FAILED: admin user create: $(printf '%s' "$out" | head -c 200)" >&2; exit 1 ;;
  esac
fi
if [ "$(admin_auth_code)" = 200 ]; then
  echo "  admin password matches the declared value"
else
  echo "  admin password differs from the declared value -- applying it"
  if ! gitea_user change-password \
      --username "${GITEA_ADMIN_USER}" \
      --password "${GITEA_ADMIN_PASSWORD}" \
      --must-change-password=false >/dev/null 2>&1; then
    echo "[init-mirrors] FAILED: gitea admin user change-password exited non-zero" >&2
    exit 1
  fi
  code=$(admin_auth_code)
  if [ "$code" != 200 ]; then
    echo "[init-mirrors] FAILED: declared admin password still rejected after change-password (HTTP $code)" >&2
    exit 1
  fi
  echo "  admin password applied and verified"
fi

# Step 2: Get or create API token
echo "-- Obtaining API token --"
# Beside .secrets in the deploy dir (the same <DEPLOY_PATH> the post-hook
# runs from), not a second hardcoded copy of deploy.remote_path.
TOKEN_FILE="$(cd "$(dirname "$0")/.." && pwd)/.gitea-token"
if [ -f "$TOKEN_FILE" ]; then
  TOKEN=$(cat "$TOKEN_FILE")
else
  TOKEN=$(admin_curl -sf -X POST "$API/users/${GITEA_ADMIN_USER}/tokens" \
    -H "Content-Type: application/json" \
    -d '{"name":"init-mirrors","scopes":["all"]}' | jq -r '.sha1') || true
  if [ -n "$TOKEN" ] && [ "$TOKEN" != "null" ]; then
    echo "$TOKEN" > "$TOKEN_FILE"
    chmod 600 "$TOKEN_FILE"
    echo "  Token created and saved"
  else
    echo "  FAIL: could not create token"
    exit 1
  fi
fi

api() { curl -sf -H "Authorization: token $TOKEN" -H "Content-Type: application/json" "$@"; }

EXCLUDE_NAMES="cloud-vault cloud-me_vault"
is_excluded() { case " $EXCLUDE_NAMES " in *" $1 "*) return 0 ;; esac; return 1; }

# remove_excluded <name> — mirror_policy.exclude, enforced by DELETION.
remove_excluded() {
  local n="$1" meta
  if meta=$(api "$API/repos/diego/$n" 2>/dev/null); then
    echo "REMOVING excluded repo diego/$n (empty=$(printf '%s' "$meta" | jq -r '.empty'), size=$(printf '%s' "$meta" | jq -r '.size'), mirror=$(printf '%s' "$meta" | jq -r '.mirror'))"
    if api -X DELETE "$API/repos/diego/$n" >/dev/null 2>&1; then
      echo "  REMOVED $n"
      tally mirrors_removed "$n"
    else
      echo "  FAIL removing excluded repo $n" >&2
      tally mirrors_remove_failed "$n: declared in mirror_policy.exclude but still present in Gitea"
    fi
  else
    echo "ABSENT diego/$n (excluded)"
  fi
}

# converge_mirror <name> <upstream> <private:true|false>
#
# EXISTS used to be the end of it, so a private mirror first created by an
# anonymous clone stayed empty forever and was counted as healthy: 13 private
# mirrors sat at empty=true, mirror_updated=0001-01-01 while the SUMMARY said
# mirrors_exists=34 mirrors_degraded=0. Gitea cannot attach credentials to an
# existing mirror, and an empty repo holds nothing to lose, so it is deleted
# and migrated again with the token.
converge_mirror() {
  local name="$1" upstream="$2" private="$3" meta auth out
  # The derived set comes from cloud-infra's inventory, which lags a
  # build.json exclude edit by a whole consolidate; without this the
  # exclusion step would delete a repo and this step re-create it, now
  # WITH the token, in the same run.
  if is_excluded "$name"; then
    echo "SKIP $name (mirror_policy.exclude; still in the derived set)"
    return 0
  fi
  if meta=$(api "$API/repos/diego/$name" 2>/dev/null); then
    if [ "$private" != true ] || [ "$(printf '%s' "$meta" | jq -r '.empty')" != true ]; then
      echo "EXISTS diego/$name"
      tally mirrors_exists "$name"
      return 0
    fi
    if [ -z "${GITHUB_MIRROR_TOKEN:-}" ]; then
      echo "  WARN: $name is private, EMPTY, and GITHUB_MIRROR_TOKEN is not set"
      tally mirrors_degraded "$name: private, empty, no GITHUB_MIRROR_TOKEN"
      return 0
    fi
    echo "REPAIRING empty private mirror diego/$name"
    if ! api -X DELETE "$API/repos/diego/$name" >/dev/null 2>&1; then
      echo "  FAIL $name: could not delete the empty mirror for re-migrate" >&2
      tally mirrors_failed "$name: empty private mirror, delete for re-migrate failed"
      return 0
    fi
  fi

  echo "Creating mirror: diego/$name <- $upstream"
  auth="{}"
  if [ "$private" = true ]; then
    if [ -z "${GITHUB_MIRROR_TOKEN:-}" ]; then
      echo "  WARN: $name is private and GITHUB_MIRROR_TOKEN is not set -- an anonymous clone yields an EMPTY mirror"
      tally mirrors_degraded "$name: private, no GITHUB_MIRROR_TOKEN — mirror will be empty"
    else
      auth=$(jq -n --arg t "$GITHUB_MIRROR_TOKEN" '{auth_token:$t}')
    fi
  fi
  PAYLOAD=$(jq -n \
    --arg clone_addr "$upstream" \
    --arg repo_name "$name" \
    --arg repo_owner "diego" \
    --arg mirror_interval "1h" \
    --argjson private "$private" \
    --argjson auth "$auth" \
    '{clone_addr:$clone_addr, repo_name:$repo_name, repo_owner:$repo_owner, mirror:true, mirror_interval:$mirror_interval, private:$private, service:"github"} + $auth')
  # Every outcome lands in exactly one tally; the SUMMARY decides the exit
  # code. The migrate is synchronous and answers with the repo, so a private
  # mirror that came back empty WITH a token is a failure, not an OK.
  if out=$(api -X POST "$API/repos/migrate" -d "$PAYLOAD" 2>&1); then
    if [ "$auth" != "{}" ] && [ "$(printf '%s' "$out" | jq -r '.empty' 2>/dev/null)" != false ]; then
      echo "  FAIL $name: migrated with GITHUB_MIRROR_TOKEN but the mirror is still empty" >&2
      tally mirrors_failed "$name: private mirror empty after authenticated migrate"
    else
      echo "  OK $name"
      tally mirrors_created "$name"
    fi
  else
    echo "  FAIL $name: $(printf '%s' "$out" | head -c 200)" >&2
    tally mirrors_failed "$name: $(printf '%s' "$out" | head -c 120)"
  fi
}

# Step 3: Ensure the mirror OWNER exists
# The create used to discard its exit status (no `set -e` in this script), so a
# failure here was invisible — and it is not survivable: every repo below is
# created under this owner, so all 29 would then fail one by one.
#
# The owner may be a USER or an ORG, and here it is a user: diego is the same
# name as GITEA_ADMIN_USER created in step 1, so `GET /orgs/diego` answers 404
# and `POST /orgs` then fails on the username collision. Checking only the org
# endpoint therefore turned a healthy instance into a hard `exit 1` before a
# single mirror was attempted — which is why 14 declared mirrors, among them
# cloud-u-containers, were silently absent while 17 pre-existing ones kept
# syncing. `/users/<name>` is checked first because that is what this deployment
# actually is; the org branch stays for a fresh instance where neither exists.
echo "-- Converging Gitea mirrors --"
if api "$API/users/diego" >/dev/null 2>&1; then
  echo "Owner diego exists (user)"
elif api "$API/orgs/diego" >/dev/null 2>&1; then
  echo "Owner diego exists (org)"
else
  echo "Creating org: diego"
  if ! api -X POST "$API/orgs" -d '{"username":"diego","visibility":"public"}' >/dev/null; then
    echo "  FAIL: could not create owner diego — no mirror can be created without it" >&2
    exit 1
  fi
fi

# Step 3.5: Enforce mirror_policy.exclude by REMOVAL, not just by omission
# The exclusion used to be applied only in the deriver, which drops the repo
# from the migrate block below — i.e. it prevented CREATION and nothing else.
# `diego/cloud-vault` was mirrored before the exclusion existed and simply
# stayed, so the credential store had a mirror in Gitea for months while the
# policy declaring it must not read as satisfied. It was harmless only because
# it was empty (private upstream, no GITHUB_MIRROR_TOKEN, anonymous clone) —
# and the WARN below actively instructs an operator to add that token, which
# is what would have started filling it.
#
# A policy that only guards creation silently fails after any manual action,
# and there was proof of exactly that. So the exclusion is now converged like
# everything else: present → deleted, absent → nothing. This runs BEFORE any
# migrate, so the excluded set is gone before a token is ever offered.
echo "-- Enforcing mirror_policy.exclude --"
remove_excluded cloud-vault
remove_excluded cloud-me_vault
# Step 4: Ensure each mirror repo exists
converge_mirror My-ai-memory https://github.com/diegonmarcos/My-ai-memory.git true
converge_mirror back-Algo https://github.com/diegonmarcos/back-Algo.git false
converge_mirror back-Graphic https://github.com/diegonmarcos/back-Graphic.git false
converge_mirror back-System https://github.com/diegonmarcos/back-System.git false
converge_mirror cloud https://github.com/diegonmarcos/cloud.git false
converge_mirror cloud-data https://github.com/diegonmarcos/cloud-data.git true
converge_mirror cloud-data-lfs https://github.com/diegonmarcos/cloud-data-lfs.git true
converge_mirror cloud-data-my-ai-memory https://github.com/diegonmarcos/cloud-data-my-ai-memory.git true
converge_mirror cloud-infra https://github.com/diegonmarcos/cloud-infra.git false
converge_mirror cloud-infra-desktop https://github.com/diegonmarcos/cloud-infra-desktop.git false
converge_mirror cloud-me https://github.com/diegonmarcos/cloud-me.git true
converge_mirror cloud-me_configs https://github.com/diegonmarcos/cloud-me_configs.git true
converge_mirror cloud-me_data-private https://github.com/diegonmarcos/cloud-me_data-private.git true
converge_mirror cloud-me_data-pub https://github.com/diegonmarcos/cloud-me_data-pub.git false
converge_mirror cloud-notes https://github.com/diegonmarcos/cloud-notes.git true
converge_mirror cloud-u-android https://github.com/diegonmarcos/cloud-u-android.git false
converge_mirror cloud-u-containers https://github.com/diegonmarcos/cloud-u-containers.git false
converge_mirror cloud-u-linux https://github.com/diegonmarcos/cloud-u-linux.git false
converge_mirror cyber-Cyberwarfare https://github.com/diegonmarcos/cyber-Cyberwarfare.git false
converge_mirror dev https://github.com/diegonmarcos/dev.git true
converge_mirror diegonmarcos https://github.com/diegonmarcos/diegonmarcos.git false
converge_mirror diegonmarcos.github.io https://github.com/diegonmarcos/diegonmarcos.github.io.git false
converge_mirror front https://github.com/diegonmarcos/front.git false
converge_mirror front-assets-cdn https://github.com/diegonmarcos/front-assets-cdn.git false
converge_mirror front-data https://github.com/diegonmarcos/front-data.git false
converge_mirror front-galaxy-gaia https://github.com/diegonmarcos/front-galaxy-gaia.git true
converge_mirror front-unity https://github.com/diegonmarcos/front-unity.git true
converge_mirror git-repos-master https://github.com/diegonmarcos/git-repos-master.git false
converge_mirror lecole42 https://github.com/diegonmarcos/lecole42.git true
converge_mirror ml-Agentic https://github.com/diegonmarcos/ml-Agentic.git false
converge_mirror ml-DataScience https://github.com/diegonmarcos/ml-DataScience.git false
converge_mirror ml-MachineLearning https://github.com/diegonmarcos/ml-MachineLearning.git false
converge_mirror ops-Mylibs https://github.com/diegonmarcos/ops-Mylibs.git false

# ── Verdict ───────────────────────────────────────────────────────────
# One machine-readable line, then the exit code.
#
# `degraded` (a private mirror that is or will be empty for want of
# GITHUB_MIRROR_TOKEN) is FATAL. It was a tolerated gap while no token was
# declared; secrets.yaml now declares one, so reaching this state means the key
# went missing from the deploy, and a phone cloning such a mirror gets an empty
# repo. That is a failed ship, not a WARN.
MIRRORS_CREATED=$(tally_count mirrors_created)
MIRRORS_EXISTS=$(tally_count mirrors_exists)
MIRRORS_FAILED=$(tally_count mirrors_failed)
MIRRORS_DEGRADED=$(tally_count mirrors_degraded)
MIRRORS_REMOVED=$(tally_count mirrors_removed)
MIRRORS_REMOVE_FAILED=$(tally_count mirrors_remove_failed)
echo "[init-mirrors] SUMMARY revision=${SHIP_REVISION:-unknown} org=diego mirrors_created=$MIRRORS_CREATED mirrors_exists=$MIRRORS_EXISTS mirrors_failed=$MIRRORS_FAILED mirrors_degraded=$MIRRORS_DEGRADED mirrors_removed=$MIRRORS_REMOVED mirrors_remove_failed=$MIRRORS_REMOVE_FAILED"

# An excluded repo that is still present is the exact failure this step exists
# to prevent, so it is fatal.
if [ "$MIRRORS_REMOVE_FAILED" -gt 0 ]; then
  echo "[init-mirrors] FAILED: $MIRRORS_REMOVE_FAILED excluded repo(s) still exist in Gitea:" >&2
  sed 's|^|[init-mirrors]   |' "$TALLY_DIR/mirrors_remove_failed" >&2
  exit 1
fi
if [ "$MIRRORS_DEGRADED" -gt 0 ]; then
  echo "[init-mirrors] FAILED: $MIRRORS_DEGRADED private mirror(s) empty for want of GITHUB_MIRROR_TOKEN:" >&2
  sed 's|^|[init-mirrors]   |' "$TALLY_DIR/mirrors_degraded" >&2
  exit 1
fi
if [ "$MIRRORS_FAILED" -gt 0 ]; then
  echo "[init-mirrors] FAILED: $MIRRORS_FAILED mirror(s) did not converge:" >&2
  sed 's|^|[init-mirrors]   |' "$TALLY_DIR/mirrors_failed" >&2
  exit 1
fi
if [ "$((MIRRORS_CREATED + MIRRORS_EXISTS))" = 0 ]; then
  # A converge that converged nothing is not a success.
  echo "[init-mirrors] FAILED: not one mirror exists or was created — this script ran but did nothing" >&2
  exit 1
fi

echo "-- Done --"
